mapper.select:
SELECT id, email_normalized, status FROM users
WHERE status = 'ACTIVE' AND id <> #{excludedUserId}
  AND email_normalized LIKE '%' || #{query} || '%'
ORDER BY email_normalized LIMIT #{limit}

DELETE FROM presence p WHERE p.last_seen_at < #{onlineSince}
    OR EXISTS (SELECT 1 FROM users u WHERE u.id = p.user_id AND u.status <> 'ACTIVE')
RETURNING p.user_id
